insert into agent_command(
    id, agent_id, command_type, status, idempotency_key, payload_json, result_json,
    attempts, max_attempts, available_at, created_by, created_at, updated_at, correlation_id,
    rollback_execution_id
) values (
    #{id}, #{agentId}, #{commandType}, #{status}, #{idempotencyKey}, #{payloadJson}, #{resultJson},
    #{attempts}, #{maxAttempts}, #{availableAt}, #{createdBy}, #{createdAt}, #{updatedAt}, #{correlationId},
    #{rollbackExecutionId}
)

mapper.update:
update agent_command
   set status = #{status},
       result_json = #{resultJson},
       error_message = #{errorMessage},
       completed_at = #{completedAt},
       updated_at = #{updatedAt}
 where id = #{id}
   and status = 'DISPATCHED'


        and attempts = #{expectedAttempts}


        and attempts = 1

update agent_command
   set status = 'FAILED',
       error_message = 'AGENT_COMMAND_MAX_ATTEMPTS_EXHAUSTED',
       completed_at = #{now},
       updated_at = #{now}
 where agent_id = #{agentId}
   and status = 'DISPATCHED'
   and lease_expires_at <= #{now}
   and attempts >= max_attempts

update agent_instance
   set status = #{status},
       updated_at = #{updatedAt}
 where id = #{id}

update rollback_execution
   set status = #{status},
       finished_at = #{finishedAt}
 where id = #{id}
   and status = 'DISPATCHED'

update rollout_instance_execution
   set status = #{status},
       error_message = #{errorMessage},
       finished_at = #{finishedAt},
       version = version + 1,
       updated_by = #{updatedBy},
       updated_at = #{updatedAt}
 where id = #{id}
   and status = 'WAITING_AGENT'
   and version = #{version}

update operation_plan
   set status = #{status},
       version = #{version},
       updated_by = #{updatedBy},
       updated_at = #{updatedAt}
 where id = #{id}
   and status = 'RUNNING'
   and version = #{currentVersion}

update rule_runtime_status
   set status = 'ACTIVE',
       last_error = null,
       updated_at = #{updatedAt}
 where rule_id = #{ruleId}
   and rule_version = #{ruleVersion}
   and instance_id = #{instanceId}

